// Interfaces/IClockEntryRepository.cs
Task<ClockEntry?> GetClockEntry(int employeeId, CancellationToken cancellationToken = default);

// Models/ClockEntry.cs
public void ClockOutEmployee(DateTime clockOut)
{
    if (ClockOut != null)
    {
        throw new InvalidOperationException("Employee can only clock out once");
    }
    ClockOut = clockOut;
}

// Services/ClockEntryService.cs -- the real implementation
public async Task Clockout(int employeeId)
{
    ClockEntry? clockEntry = await _clockEntryRepository.GetClockEntry(employeeId);

    if (clockEntry == null)
    {
        throw new InvalidOperationException("Employee is not currently clocked in ");
    }

    clockEntry.ClockOutEmployee(DateTime.Now);
    _clockEntryRepository.SaveClockEntry(clockEntry);
}

